import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';

const ProfilePage = () => {
  const { user, loading: authLoading } = useAuth();
  const [profile, setProfile] = useState(null);
  const [loading, setLoading] = useState(true);
  const [editing, setEditing] = useState(false);
  const [editData, setEditData] = useState({});
  const [message, setMessage] = useState('');

  useEffect(() => {
    if (user) {
      setProfile(user);
      setEditData({
        displayName: user.displayName,
        robloxUsername: user.robloxUsername
      });
    }
    setLoading(false);
  }, [user]);

  const handleEditToggle = () => {
    setEditing(!editing);
    if (!editing) {
      setEditData({
        displayName: profile.displayName,
        robloxUsername: profile.robloxUsername
      });
    }
  };

  const handleSave = async () => {
    try {
      // In a real app, you would make an API call to update the user profile
      // For now, we'll just update the local state
      const updatedProfile = {
        ...profile,
        displayName: editData.displayName,
        robloxUsername: editData.robloxUsername
      };

      setProfile(updatedProfile);
      setEditing(false);
      setMessage('Profile updated successfully!');

      // Clear the message after 3 seconds
      setTimeout(() => setMessage(''), 3000);
    } catch (error) {
      console.error('Error updating profile:', error);
      setMessage('Error updating profile');
    }
  };

  const handleChange = (e) => {
    setEditData({
      ...editData,
      [e.target.name]: e.target.value
    });
  };

  if (authLoading || loading) {
    return (
      <div className="loading-container">
        <div className="loading-spinner"></div>
        <p>Loading profile...</p>
      </div>
    );
  }

  if (!profile) {
    return (
      <div className="error-container">
        <p>Error loading profile</p>
      </div>
    );
  }

  return (
    <div className="profile-container">
      <div className="profile-header">
        <h1>User Profile</h1>
        <button className="btn btn-primary" onClick={handleEditToggle}>
          {editing ? 'Cancel' : 'Edit Profile'}
        </button>
      </div>

      {message && <div className="message">{message}</div>}

      <div className="profile-card">
        <div className="profile-image-section">
          <img 
            src={profile?.avatar || `https://www.roblox.com/headshot-thumbnail/image?userId=${profile?.id}&width=420&height=420&format=png`} 
            alt={`${profile?.displayName}'s avatar`}
            className="profile-image"
          />
        </div>

        <div className="profile-details">
          {editing ? (
            <div className="edit-form">
              <div className="form-group">
                <label htmlFor="displayName">Display Name:</label>
                <input
                  type="text"
                  id="displayName"
                  name="displayName"
                  value={editData.displayName}
                  onChange={handleChange}
                  className="form-control"
                />
              </div>

              <div className="form-group">
                <label htmlFor="robloxUsername">Roblox Username:</label>
                <input
                  type="text"
                  id="robloxUsername"
                  name="robloxUsername"
                  value={editData.robloxUsername}
                  onChange={handleChange}
                  className="form-control"
                />
              </div>

              <button className="btn btn-success" onClick={handleSave}>Save Changes</button>
            </div>
          ) : (
            <>
              <div className="profile-field">
                <label>Display Name:</label>
                <p>{profile?.displayName}</p>
              </div>

              <div className="profile-field">
                <label>Roblox Username:</label>
                <p>{profile?.robloxUsername}</p>
              </div>

              <div className="profile-field">
                <label>User ID:</label>
                <p>{profile?.id}</p>
              </div>

              <div className="profile-stats">
                <div className="stat">
                  <span className="stat-value">{profile?.gamesPlayed || 0}</span>
                  <span className="stat-label">Games Played</span>
                </div>

                <div className="stat">
                  <span className="stat-value">{profile?.gamesWon || 0}</span>
                  <span className="stat-label">Games Won</span>
                </div>

                <div className="stat">
                  <span className="stat-value">{profile?.gamesLost || 0}</span>
                  <span className="stat-label">Games Lost</span>
                </div>
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
};

export default ProfilePage;
